

if (!customElements.get('address-country')) {
    customElements.define('address-country', class AddressCountry extends HTMLElement {
        constructor() {
            super();

            this.select = this.querySelector('select');
            this.provincesSelectBlock = this.closest('form').querySelector('.js-provinces-select-wrap');
            this.select.addEventListener('change',this.selectChange.bind(this))

            this.init();
        }
        init(){
            if(this.select.dataset.default){
                for (var i = 0, count = this.select.options.length; i < count; i++) {
                    var option = this.select.options[i];
                    if (this.select.dataset.default == option.value || this.select.dataset.default == option.innerHTML) {
                        this.select.selectedIndex = i;
						initCountrySelect(this.querySelector('select'));
                        let event = new Event('change');
                        this.select.dispatchEvent(event);
                        return i;
                    }
                }
            }else{
				initCountrySelect(this.querySelector('select'));
			}
        }
        // provinces
        selectChange(){
            let provincesSelectBlock = this.provincesSelectBlock;
            let selectedOption = this.select.options[this.select.selectedIndex];
            let dataProvinces = selectedOption.dataset.provinces;
            let provinces = JSON.parse(dataProvinces);
			let provinceSelect = this.provincesSelectBlock.querySelector('select');
            if(provinces && provinces.length == 0){
				if(provinceSelect.tomselect){
					provinceSelect.tomselect.destroy();
				}
				provinceSelect.innerHTML = '';
                provincesSelectBlock.style.display = 'none';
            }else{
				if(provinceSelect.tomselect){
					provinceSelect.tomselect.destroy();
				}
				provinceSelect.innerHTML = '';
                provinces.forEach(item =>{
                    let optionBlock = document.createElement('option');
                    optionBlock.value = item[0];
                    optionBlock.innerHTML = item[0];
					if(provinceSelect.dataset.default == item[0] ){
						optionBlock.setAttribute('selected', 'selected')
					}
                    provinceSelect.appendChild(optionBlock);
                });
				initCountrySelect(provinceSelect);
                provincesSelectBlock.style.display = 'block';
            }
        }

    });
}

let deleteAddressButtons = document.querySelectorAll('.js-delete-address');
if(deleteAddressButtons){
    deleteAddressButtons.forEach(button => {
        button.addEventListener('click',function (){
            if (confirm(this.getAttribute('data-confirm-message'))) {
                Shopify.postLink(this.dataset.target, {
                    parameters: { _method: 'delete' },
                });
            }
        });
    });
}
let toggleAddressForm = document.querySelectorAll('.js-toggle-form-address');
if(toggleAddressForm){
    toggleAddressForm.forEach(button => {
        button.addEventListener('click',function (){
			if(this.closest('.vip-profile-info-item')){
				this.closest('.vip-profile-info-item').classList.add('edit');
			}
        });
    });
}
let cancelAddressForm = document.querySelectorAll('.js-form-cancel');
if(cancelAddressForm){
    cancelAddressForm.forEach(button => {
        button.addEventListener('click',function (){
			if(this.closest('.vip-profile-info-item')){
				this.closest('.vip-profile-info-item').classList.remove('edit');
			}
        });
    });
}
let addNewAddress = document.querySelectorAll('.js-add-new-address');
if(addNewAddress){
	addNewAddress.forEach(button => {
        button.addEventListener('click',function (){
			if(document.querySelector('.js-new-address-wrapper')){
				document.querySelector('.js-new-address-wrapper').classList.add('edit');
				document.querySelector('.js-new-address-wrapper').scrollIntoView({ behavior: "smooth", block: "start", inline: "nearest" });
			}
        });
    });
}

let cancelNewAddress = document.querySelectorAll('.js-cancel-new-address');
if(cancelNewAddress){
	cancelNewAddress.forEach(button => {
        button.addEventListener('click',function (){
			if(document.querySelector('.js-new-address-wrapper')){
				document.querySelector('.js-new-address-wrapper').classList.remove('edit');
			}
        });
    });
}
function initCountrySelect(select){
	if(select && !select.tomselect){
		new TomSelect(select,{
			controlInput: null,
			maxOptions: null,
			render: {
				item: function (data, escape) {
					return `<div class="select-label"
							<span>
							${escape(data.text)}
							</span>
							<span class="icon-wrapper">
								<span class="icon icon-selet-arrow"></span>
							</span>
						</div>`;
				},
			}
		});
	}
}
